# Guvizel (Carpathia No. 10162) sculpted from nothing on the skeleton and clips of the game's own export of it
# (sculptkit.py):
#   blender --background --factory-startup --python sculpts/guvizel.py -- <the export's Guvizel.glb> <out.glb>
#
# The game has no sculptor of its own for Guvizel: its export is a fish generated by rule, of which only the bones, the
# clips and the size are taken (built to the export's length, its longest side, so that the head, tail and tail fin
# joints land on the goby's own parts).
#
# The design, from the project's picture (docs/art/reference/gemini/carpathia/10162-Guvizel.jpg): a small round-headed
# goby of the Black Sea shore. The head is half the fish, round and wide, with big puffy tan lips standing forward at
# its front; a round puffed cheek behind the mouth; two big bulging eyes high on the head's top sides, white with a
# pale grey-green iris, a dark pupil and a glint. The body tapers back to a short stalk and a round fan of a tail; the
# skin sandy and mottled, dark brown and tan blotches with teal flecks, the belly pale. A spiny fan of a dorsal fin with
# a scalloped edge; a broad fan of a pectoral fin on each flank; the pelvic fins fused under the chin into a little
# sucker disc; a low anal fin under the tail stalk. Fins pale sand with darker rays.
# The skeleton: body (0, 0, 0.175), head (0, -0.195, 0.195), tail (0, 0.365, 0.175), tailFin (0, 0.545, 0.175),
# dorsal (0, 0, 0.287), finR/L (+-0.09, -0.097, 0.135). The goby is a round fish twice as tall as the generated one, so
# its middle stands above the body joint; the dorsal and the pectorals stay on body (their joints lie far under their
# roots), the sucker disc's two halves go to finR and finL, whose joints are where it is.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import Kit, ell, tube, slab, srgb, inside, unit, eye_look, args

SAND, BELLY, BLOTCH, TAN, TEAL = "#B7A07A", "#DCD6C2", "#5A4733", "#8F7756", "#5C969D"
LIPS, LIPLINE, FIN, RAY = "#C9A27C", "#6B4E38", "#CDC3AC", "#988A6E"
WHITE, IRIS, INK = "#EEF1EA", "#A3B39F", "#17191A"

HEAD_C, HEAD_R = np.array([0.0, -0.21, 0.43]), np.array([0.215, 0.27, 0.27])
SOCK_C, SOCK_R = np.array([0.118, -0.265, 0.6]), 0.085
EYE_D = unit(0.62, -0.62, 0.48)


def body(k):
    k.add("head", ell(HEAD_C, HEAD_R), SAND, "head")
    k.add("cheek", ell((0.12, -0.12, 0.39), (0.11, 0.15, 0.15)), SAND, "head", mirror=True)
    k.add("socket", ell(SOCK_C, (SOCK_R, SOCK_R, SOCK_R * 0.95)), SAND, "head", mirror=True)
    k.add("trunk", ell((0, 0.05, 0.4), (0.18, 0.3, 0.245)), SAND, "body")
    V, F = tube([(0, 0.18, 0.39), (0, 0.29, 0.36), (0, 0.37, 0.335)], [0.17, 0.115, 0.08])
    V[:, 0] *= 0.78
    k.add("stalk", (V, F), SAND, "tail")
    # the pale belly, then the blotches and flecks over the back and the flanks
    k.paint(lambda P: inside(P[:, 2] - (0.29 + 0.06 * np.clip(-P[:, 1] - 0.1, 0, 1)), 0.01), BELLY)
    rs = np.random.RandomState(21)
    def spots(n, rmin, rmax, zmin):
        """Blotches placed round the fish's long axis (an angle from the top and a place along it), so each lies on
        the skin whatever the body's girth there."""
        A = rs.uniform(-2.0, 2.0, n); Y = rs.uniform(-0.42, 0.36, n); R = rs.uniform(rmin, rmax, n)
        def mask(P):
            ang = np.arctan2(P[:, 0], P[:, 2] - 0.42) * 0.23
            m = np.zeros(len(P))
            for a, y, r in zip(A, Y, R):
                m = np.maximum(m, inside(np.hypot(ang - a * 0.23, P[:, 1] - y) - r, 0.003))
            return m * inside(zmin - P[:, 2], 0.01) * inside(-0.4 - P[:, 1], 0.01)
        return mask
    k.paint(spots(75, 0.026, 0.045, 0.31), TAN)
    k.paint(spots(90, 0.018, 0.034, 0.32), BLOTCH)
    k.paint(spots(50, 0.012, 0.018, 0.32), TEAL)


def lips(k):
    """The big puffy lips standing forward at the front of the head, a dark line where they meet."""
    k.add("lipline", ell((0, -0.49, 0.448), (0.092, 0.04, 0.014)), LIPLINE, "head", fuse=False, surface="skin")
    k.add("upperlip", ell((0, -0.5, 0.494), (0.112, 0.068, 0.05), rot=(-12, 0, 0)), LIPS, "head", fuse=False,
          surface="skin")
    k.add("lowerlip", ell((0, -0.485, 0.405), (0.1, 0.062, 0.045), rot=(10, 0, 0)), LIPS, "head", fuse=False,
          surface="skin")


def fins(k):
    # The dorsal: a spiny fan with a scalloped edge, turned 40 degrees toward +X
    yaw = math.radians(40)
    ex = (math.sin(yaw), math.cos(yaw), 0.0)
    top = []
    for i in range(9):
        t = i / 8
        a = -0.1 + 0.3 * t
        b = 0.02 + 0.16 * math.sin(math.pi * (0.15 + 0.7 * t)) * (1.1 - 0.5 * t) + (0.018 if i % 2 == 0 else 0.0)
        top.append((a, b))
    outline = [(-0.12, -0.03)] + top + [(0.22, 0.0), (0.22, -0.03)]
    k.add("dorsal", slab(outline, (0, 0.02, 0.61), ex, (0, 0, 1), 0.016), FIN, "body", fuse=False, surface="scales")
    for i in range(4):
        a = -0.06 + 0.07 * i
        k.add(f"dorsalray{i}", slab([(a - 0.01, -0.02), (a + 0.01, -0.02), (a + 0.03, 0.13 - 0.02 * i),
                                     (a + 0.012, 0.135 - 0.02 * i)], (0, 0.02, 0.61), ex, (0, 0, 1), 0.024), RAY,
              "body", fuse=False, surface="scales")
    # The tail: a round fan, turned 45 degrees toward +X
    yaw = math.radians(45)
    ex = (math.sin(yaw), math.cos(yaw), 0.0)
    fan = [(0.0, -0.05)] + [(0.04 + 0.13 * math.cos(t), 0.14 * math.sin(t)) for t in np.linspace(-1.25, 1.25, 11)] + [(0.0, 0.05)]
    k.add("tailfin", slab(fan, (0, 0.36, 0.335), ex, (0, 0, 1), 0.016), FIN, "tailFin", fuse=False, surface="scales")
    for t in (-0.75, -0.25, 0.25, 0.75):
        d = np.array([math.cos(t), math.sin(t)])
        p = np.array([-d[1], d[0]]) * 0.011
        k.add(f"tailray{t}", slab([tuple(d * 0.03 - p), tuple(d * 0.03 + p), tuple(d * 0.15 + p * 1.2), tuple(d * 0.15 - p * 1.2)],
                                  (0, 0.36, 0.335), ex, (0, 0, 1), 0.024), RAY, "tailFin", fuse=False, surface="scales")
    # The anal fin: low under the tail stalk, turned toward +X too
    yaw = math.radians(40)
    ex = (math.sin(yaw), math.cos(yaw), 0.0)
    k.add("anal", slab([(-0.08, 0.02), (0.1, 0.02), (0.13, -0.04), (0.05, -0.075), (-0.05, -0.06)],
                       (0, 0.2, 0.215), ex, (0, 0, 1), 0.016), FIN, "body", fuse=False, surface="scales")
    # The pectorals: broad fans on the flanks behind the cheek, their faces to the front and out
    ex, ez = unit(0.2, 0.8, -0.55), unit(0.55, 0.3, 0.78)
    fan = [(0.0, -0.035), (0.07, -0.1), (0.16, -0.105), (0.215, -0.035), (0.205, 0.05), (0.15, 0.1), (0.06, 0.085),
           (0.0, 0.035)]
    k.add("pectoral", slab(fan, (0.2, -0.02, 0.36), ex, ez, 0.016), FIN, "body", fuse=False, surface="scales",
          mirror=True)
    for j, t in enumerate((-0.4, 0.0, 0.4)):
        d = np.array([math.cos(t), math.sin(t)])
        p = np.array([-d[1], d[0]]) * 0.011
        k.add(f"pecray{j}", slab([tuple(d * 0.02 - p), tuple(d * 0.02 + p), tuple(d * 0.18 + p * 1.2),
                                  tuple(d * 0.18 - p * 1.2)], (0.2, -0.02, 0.36), ex, ez, 0.024), RAY, "body",
              fuse=False, surface="scales", mirror=True)
    # The pelvic fins fused under the chin into a little sucker disc, a half to each fin bone
    k.add("sucker", ell((0.06, -0.17, 0.17), (0.078, 0.12, 0.032), rot=(0, -16, 0)), FIN, "fin{s}", fuse=False,
          surface="scales", mirror=True)


# --- the eyes: big, bulging on the head's top sides, white with a pale iris, a dark pupil, a glint ---------------------
CW, CI, CK = srgb(WHITE), srgb(IRIS), srgb(INK)


def eye_open(u, v):
    c = np.tile(CW, (len(u), 1))
    c[((u + 0.08) / 0.62) ** 2 + ((v + 0.02) / 0.64) ** 2 < 1] = CI
    c[((u + 0.08) / 0.4) ** 2 + ((v + 0.02) / 0.42) ** 2 < 1] = CK
    c[((u - 0.1) / 0.17) ** 2 + ((v - 0.2) / 0.17) ** 2 < 1] = CW
    c[u * u + v * v > 0.9 ** 2] = srgb("#5A4C3A")
    return c


def eyes(k, state):
    lk = eye_look(state, eye_open, srgb(SAND), CK, line=0.18)
    for s in (1, -1):
        col = lk if s > 0 else (lambda uu, v, f=lk: f(-uu, v))
        d = EYE_D * (s, 1, 1)
        k.decal(SOCK_C * (s, 1, 1) + d * SOCK_R, d, (0.068, 0.068), col, eps=0.003, rings=20, segs=56,
                up=(0, 0.3, 1))


def guvizel(src, out):
    k = Kit(src, coat="scales")
    body(k)
    lips(k)
    fins(k)
    k.build(voxel=0.0072, smooth=4, band=0.006, wband=0.07)
    k.eye_states(lambda st: eyes(k, st))
    k.export(out)


if __name__ == "__main__":
    guvizel(*args())
